package com.chondrimaishrat.elearning.payment;
import com.chondrimaishrat.elearning.course.Course; import com.chondrimaishrat.elearning.user.UserAccount; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="payments") public class Payment {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="student_id") private UserAccount student; @ManyToOne(optional=false) @JoinColumn(name="course_id") private Course course; @Column(nullable=false,precision=10,scale=2) private BigDecimal amount; @Column(nullable=false,length=80,unique=true) private String reference; @Column(nullable=false) private LocalDateTime paidAt; protected Payment(){} public Payment(UserAccount s,Course c,BigDecimal a,String ref){student=s;course=c;amount=a;reference=ref;paidAt=LocalDateTime.now();}}
